102	/** The first lines of a regular file, read without following a link and at most DELETE_PEEK_BYTES. */
103	function peek(file: string, size: number): string[] {
104	  if (size === 0) return ["(empty file)"];
105	  let descriptor: number | undefined;
106	  try {
107	    descriptor = fs.openSync(file, fs.constants.O_RDONLY | fs.constants.O_NOFOLLOW);
108	    const buffer = Buffer.alloc(Math.min(size, DELETE_PEEK_BYTES));
109	    const read = fs.readSync(descriptor, buffer, 0, buffer.length, 0);
110	    const bytes = buffer.subarray(0, read);
111	    if (bytes.includes(0)) return ["binary content not shown"];
112	    const more = size > read;
113	    let lines = redactSecrets(bytes.toString("utf-8")).split(/\r?\n/);
114	    if (lines.at(-1) === "") lines.pop();
115	    else if (more && lines.length > 1) lines.pop(); // the read ended inside a line
116	    const rows = lines.slice(0, DELETE_PEEK_LINES).map((row) => `▎ ${cut(row)}`);
117	    if (more || lines.length > DELETE_PEEK_LINES) rows.push("… more content not shown");
118	    return rows;
119	  } catch {
120	    return ["content could not be read"];
121	  } finally {
122	    if (descriptor !== undefined) try { fs.closeSync(descriptor); } catch { /* nothing to release */ }
123	  }
124	}
