126	/** Human text for the delete approval; never throws. */
127	export function describeDeletion(workspace: string, args: Record<string, any>, limit = DELETE_VISIT_LIMIT): string {
128	  const given = typeof args.path === "string" ? args.path : "";
129	  const shown = cut(given);
130	  const recursive = args.recursive === true;
131	  try {
132	    const root = fs.realpathSync(workspace);
133	    const lexical = path.resolve(root, given);
134	    const rel = path.relative(root, lexical);
135	    const header = [shown || "(no path given)"];
136	    if (rel && !rel.startsWith("..") && !path.isAbsolute(rel) && given.replace(/^\.\//, "") !== rel) header.push(`resolves to ${cut(rel)}`);
137	    if (!given || !rel || rel.startsWith("..") || path.isAbsolute(rel)) {
138	      return [...header, "outside the workspace, or not a file or folder inside it · the delete will be refused. Nothing there is shown."].join("\n");
139	    }
140	    let parent: string;
141	    try {
142	      parent = fs.realpathSync(path.dirname(lexical));
143	    } catch {
144	      return [...header, "does not exist · the delete will fail."].join("\n");
145	    }
146	    if (!inside(root, parent)) {
147	      return [...header, "outside the workspace (through a link) · the delete will be refused. Nothing there is shown."].join("\n");
148	    }
149	    const target = path.join(parent, path.basename(lexical));
150	    let stat: fs.Stats;
151	    try {
152	      stat = fs.lstatSync(target);
153	    } catch {
154	      return [...header, "does not exist · the delete will fail."].join("\n");
155	    }
156	    if (stat.isSymbolicLink()) {
157	      let pointsTo = "";
158	      try { pointsTo = fs.readlinkSync(target); } catch { /* shown without it */ }
159	      return [...header, `symbolic link${pointsTo ? ` -> ${cut(pointsTo)}` : ""}`, "Only the link is removed; what it points to is not touched or shown."].join("\n");
160	    }
161	    if (stat.isFile()) {
162	      return [...header, `file · ${formatBytes(stat.size)}`, "Only this file is removed.", ...(stat.size === 0 ? [] : ["start of the file:"]), ...peek(target, stat.size)].join("\n");
163	    }
164	    if (stat.isDirectory()) {
165	      const found = walk(target, limit);
166	      const parts = [
167	        found.files ? plural(found.files, "file") : "",
168	        found.folders ? plural(found.folders, "folder") : "",
169	        found.links ? plural(found.links, "link") : "",
170	        found.others ? plural(found.others, "special file") : "",
171	      ].filter(Boolean);
172	      const count = found.truncated ? `at least ${limit} entries` : plural(found.counted, "entry", "entries");
173	      const lines = [
174	        ...header,
175	        `directory · ${count}${parts.length ? ` (${parts.join(", ")})` : ""} · ${formatBytes(found.bytes)}${found.truncated ? "+" : ""}`,
176	        recursive ? "Everything inside it is removed. Links inside are removed, not followed." : "This will be refused: a directory needs recursive=true, and the model did not set it.",
177	      ];
178	      if (found.unreadable) lines.push("some entries could not be read, so the count may be low");
179	      if (found.listing.length > 0) lines.push("contents:", ...found.listing.map((name) => `▎ ${cut(name)}`));
180	      const unlisted = found.counted - found.listing.length;
181	      if (unlisted > 0 || found.truncated) lines.push(`… ${found.truncated && unlisted <= 0 ? "more" : unlisted} more entries not listed`);
182	      return lines.join("\n");
183	    }
184	    return [...header, "special file (not a regular file or folder) · contents are not shown."].join("\n");
185	  } catch {
186	    return [shown || "(no path given)", "could not be inspected · the delete will still be attempted as written."].join("\n");
187	  }
188	}
