    if (approved && always) {
      this.alwaysApprove = true;
      this.mode = "auto";
      this.app.getAgent().setApprovalMode("auto");
      this.emitSessionState();
    }
    pending.settle(approved);
  }

  private requestCheckpointChoice(
    turnId: string,
    signal: AbortSignal,
    message = "Sensitive content blocked the checkpoint. Choose 1 read-only, 2 continue without a rollback checkpoint, 3 create a checkpoint anyway (may persist sensitive content), 4 cancel this turn, or 5 re-enter the instruction.",
    choices: readonly CheckpointChoice[] = ["read_only", "without_checkpoint", "allow_sensitive", "cancel", "other"],
  ): Promise<CheckpointChoice> {
    if (signal.aborted) return Promise.resolve("cancel");
    const id = `checkpoint-choice-${++this.approvalSeq}`;
    return new Promise((resolve) => {
      const settle = (choice: CheckpointChoice) => {
        signal.removeEventListener("abort", onAbort);
        this.pendingCheckpointChoice = undefined;
        resolve(choice);
      };
      const onAbort = () => settle("cancel");
      signal.addEventListener("abort", onAbort, { once: true });
      this.pendingCheckpointChoice = { id, choices, settle };
      this.emit({
        type: "checkpoint.choice.request",
        id,
        turn_id: turnId,
        message,
      });
    });
  }

  private resolveCheckpointChoice(id: string, choice: CheckpointChoice): void {
    const pending = this.pendingCheckpointChoice;
    if (!pending || pending.id !== id) {
      this.emit({ type: "error", id, code: "NOT_FOUND", message: `No pending checkpoint choice with id ${id}.` });
      return;
    }
    if (!pending.choices.includes(choice)) {
      this.emit({ type: "error", id, code: "BAD_REQUEST", message: "That choice is not available for this checkpoint failure." });
      return;
    }
    pending.settle(choice);
  }

  private slash(id: string, command: string, args: string): void {
    if (this.app.getAgent().getApprovalMode() === "read-only" && !readOnlySlashAllowed(command, args)) {
      this.emit({
        type: "slash.result",
        id,
        command: command.trim().replace(/^\//, "").toLowerCase(),
        success: false,
        output: "This command is disabled while the session is in read-only mode.",
      });
      return;
    }
    // /compact while work runs is queued, never refused or run concurrently: see queueCompaction.
    const stat = fs.statSync(target);
    if (!stat.isFile() || stat.size > MAX_REVIEW_TEXT * 4) return { exists: true, text: null };
    return { exists: true, text: fs.readFileSync(target, "utf-8") };
  } catch {
    return { exists: true, text: null };
  }
}

export function approvalReview(tool: string, args: Record<string, any>, workspace: string): ApprovalReview {
  const file = typeof args.path === "string" ? args.path : "";
  switch (tool) {
    case "edit_file": {
      const before = capped(String(args.old_content ?? ""));
      const after = capped(String(args.new_content ?? ""));
      return { kind: "change", path: file, before: before.text, after: after.text, created: false, truncated: before.truncated || after.truncated };
    }
    case "write_file": {
      const current = currentText(workspace, file);
      const before = current.text === null ? null : capped(current.text);
      const after = capped(String(args.content ?? ""));
      return {
        kind: "change",
        path: file,
        before: before ? before.text : null,
        after: after.text,
        created: !current.exists,
        truncated: after.truncated || Boolean(before?.truncated),
      };
    }
    case "patch_file": {
      const patch = capped(String(args.patch ?? ""));
      return { kind: "patch", path: file, patch: patch.text, truncated: patch.truncated };
    }
    // Text, so an older client shows it as it shows any arguments; built without reading outside the workspace.
    case "delete_file":
      return { kind: "args", text: redactSecrets(describeDeletion(workspace, args)), truncated: false };
    case "run_command":
      return { kind: "command", command: redactSecrets(String(args.command ?? "")) };
    case "verifier": {
      const command = redactSecrets(String(args.command ?? ""));
      const script = args.script !== undefined ? capped(String(args.script)).text : undefined;
      const detail = args.detail !== undefined ? redactSecrets(String(args.detail)) : undefined;
      return { kind: "verifier", command, script, detail };
    }
    default: {
      const text = capped(JSON.stringify(args, null, 2));
      return { kind: "args", text: text.text, truncated: text.truncated };
    }
  }
}

